const LOAD_TIPS = ['Click any pull card at the top to jump to it.', 'Click a player\'s name anywhere to open their page.', 'Hover a spell\'s name to see what it does.',
  'The wipe filter stops counting after a set number of deaths, so the end of a wipe doesn\'t pile up mistakes.', 'Paste your NSRT note on Assignments: soaks, kicks, orbs and cooldowns get checked on every pull.',
  'On Latest pull, every box opens the tab with its details.', 'Summary shows the whole night: how far each pull got, and what kept going wrong.', 'Players gives everyone one grade: half mechanics, half the Report card.'];
let LD_LAST = -1;
function loadCard(title, line, frac, id) {
  let k = Math.floor(Math.random() * DANCERS.length); if (k === LD_LAST) k = (k + 1) % DANCERS.length; LD_LAST = k;
  const tip = LOAD_TIPS[Math.floor(Math.random() * LOAD_TIPS.length)];
  return '<div class="ld" role="status" aria-live="polite"><svg class="ld-d ld-' + DANCERS[k][0] + '" viewBox="0 0 80 90" aria-hidden="true"><ellipse class="ld-sh" cx="40" cy="84" rx="17" ry="3.5"/><g class="ld-body">' + DANCERS[k][2]() + '</g></svg><div class="ld-cap">' + esc(DANCERS[k][1]) + '</div>' +
    '<div class="ld-t">' + esc(title) + '</div><div class="ld-l"' + (id ? ' id="' + id + '"' : '') + '>' + esc(line || '') + '</div>' +
    '<div class="ld-b' + (frac == null ? ' ind' : '') + '"><i' + (frac == null ? '' : ' style="width:' + (100 * frac).toFixed(1) + '%"') + '></i></div><div class="ld-tip"><b>Tip</b> · ' + esc(tip) + '</div></div>';
}
// (the line and the bar of the loading card inside `where`, in place, so the dancer keeps dancing)
function loadSet(where, line, frac) {
  const el = typeof where === 'string' ? document.querySelector(where) : where, c = el && (el.classList && el.classList.contains('ld') ? el : el.querySelector('.ld')); if (!c) return;
  const l = c.querySelector('.ld-l'); if (l) l.textContent = line;
  const b = c.querySelector('.ld-b'); if (b && frac != null) { b.classList.remove('ind'); b.firstChild.style.width = (100 * Math.max(0, Math.min(1, frac))).toFixed(1) + '%'; }
}
// (a pull asked for twice at once, e.g. by the background reader and a click, is only read once)
const INFLIGHT = new Map();
function getRep(item) {
  if (CACHE.has(item)) return Promise.resolve(CACHE.get(item));
  if (!INFLIGHT.has(item)) INFLIGHT.set(item, readRep(item).finally(() => INFLIGHT.delete(item)));
  return INFLIGHT.get(item);
}
async function readRep(item) {
  if (CACHE.has(item)) return CACHE.get(item);
  let text;
  if (item.wcl) {
    const st = () => document.getElementById('loadmsg');
    const events = await WCL.loadEvents(S.wclCreds, item, (n) => { if (S.item === item && st()) st().textContent = 'Downloading ' + item.boss + ' pull ' + item.pull + ' from Warcraft Logs: ' + n.toLocaleString('en-US') + ' events…'; });
    text = WCL.translate(item, events);
  } else text = FH.dir ? await fhText(item.startByte, item.endByte) : await S.file.slice(item.startByte, item.endByte).text();
  const rep = E.analyze(item, text, { packs: S.packs, overrides: overrides() });
  // Raid audit: each player's gear (with enchants) and buffs at the pull, straight from Warcraft Logs
  if (item.wcl) {
    const evs = await WCL.loadEvents(S.wclCreds, item);
    // every spell in the report (not just this pull), so mechanics that didn't happen this pull still get game icons and tooltips
    for (const a of item.wcl.abilities.values()) { const k = String(a.name || '').toLowerCase(); if (k && a.gameID > 1 && !E.SPELLID.has(k)) E.SPELLID.set(k, a.gameID); }
    rep.combatants = evs.filter((e) => e.type === 'combatantinfo').map((e) => ({ name: (item.wcl.actors.get(e.sourceID) || {}).name, gear: e.gear || [], auras: e.auras || [], self: e.sourceID, talents: e.talentTree || [],
      // stats as ratings, when the pull started (WCL gives melee/ranged/spell versions of crit and haste; the highest is the one that counts)
      stats: { strength: e.strength, agility: e.agility, intellect: e.intellect, stamina: e.stamina, crit: Math.max(e.critMelee || 0, e.critRanged || 0, e.critSpell || 0), haste: Math.max(e.hasteMelee || 0, e.hasteRanged || 0, e.hasteSpell || 0),
        mastery: e.mastery, versatility: e.versatilityDamageDone, leech: e.leech, avoidance: e.avoidance, speed: e.speed, armor: e.armor } }));
  }
  // own combat logs: gear, stats and buffs come from each player's COMBATANT_INFO line (names and icons are looked up
  // when the Raid audit opens)
  if (!item.wcl && rep.combatantsRaw && rep.combatantsRaw.length) rep.combatants = rep.combatantsRaw.filter((c) => rep.players.has(c.guid)).map((c) => ({ name: rep.players.get(c.guid).name, gear: c.gear, auras: c.auras, self: c.guid, stats: c.stats, talents: c.talents || [] }));
  applyNote(rep);
  CACHE.set(item, rep);
  histSave(rep);
  return rep;
}
async function select(item) {
  S.miss = 0; syncUrl(item);
  S.item = item; S.mPlayer = null; S.pPlayer = null; S.death = 0;
  document.querySelectorAll('.pull').forEach((b) => b.classList.toggle('sel', ITEMS[+b.dataset.i] === item));
  $('#main').innerHTML = '<div class="empty">' + loadCard('Opening ' + item.boss + (item.pull ? ', pull ' + item.pull : ''), 'Reading the pull…', null, 'loadmsg') + '</div>';
  let rep;
  try { rep = await getRep(item); }
  catch (err) {
    if (S.item !== item) return;
    $('#main').innerHTML = '<div class="empty"><p class="muted">Couldn\'t analyze this pull: ' + esc(err.message) + '</p><button class="btn primary" id="pullRetry" type="button">Try again</button></div>'; console.error(err);
    $('#pullRetry').onclick = () => select(item); return;
  }
  if (S.item !== item) return;
  try { S.rep = rep; }
  catch (err) { $('#main').innerHTML = '<div class="empty"><p class="muted">Couldn\'t analyze this pull: ' + esc(err.message) + '</p></div>'; console.error(err); return; }
  renderMain();
  bgFetch(item); // (the next pull, then the rest of this boss's pulls, download in the background)
}
// Warcraft Logs reports: once a pull is up, this boss's other pulls in the report download quietly, the next pull first,
// then newest first, one at a time with a pause, into this browser's saved pulls. Summary, All pulls and the next click
// then only read them, without the wait for Warcraft Logs. It moves on to a new boss when you do; a refusal (too many
// requests at once) stops it until the next pull you open.
let BG_TOK = 0, BG_KEY = null;
function bgFetch(item) {
  if (!item.wcl || !S.index) return; const key = item.wcl.code + '|' + item.id + '|' + item.diffId; if (BG_KEY === key) return; BG_KEY = key;
  const tok = ++BG_TOK, idx = S.index, next = idx.bosses[idx.bosses.indexOf(item) + 1];
  const list = idx.bosses.filter((b) => b.wcl && b !== item && b.id === item.id && b.diffId === item.diffId && !CACHE.has(b));
  list.sort((a, b) => (b === next) - (a === next) || idx.bosses.indexOf(b) - idx.bosses.indexOf(a));
  // (paced to about 85 requests a minute, under half the site's fair share of 180, so what you ask for never waits on it;
  // and it holds off while a loading screen is up: that's you waiting on something)
  (async () => { for (const b of list) { if (tok !== BG_TOK || S.index !== idx) return;
    while (document.querySelector('#main .ld') && tok === BG_TOK) await new Promise((r) => setTimeout(r, 1500));
    try { if (!(await WCL.isSaved(b))) { let pages = 0; await WCL.loadEvents(S.wclCreds, b, () => pages++); await new Promise((r) => setTimeout(r, Math.max(1500, pages * 700))); } } catch (e) { if (tok === BG_TOK) BG_KEY = null; return; } } })();
}

// ---------- main frame ----------
// Tabs: Latest pull (the live recap, always one pull), Assignments (the NSRT audit), Mechanics (the fight audit),
// Summary (the night, always all pulls) and Player audit (gear, consumables and survival kit). Damage, Healing and
// Damage taken are hidden for now (to be redone); meter() stays for that.
const TABS = [['overview', 'Assignments'], ['audit', 'Mechanics'], ['perf', 'Performance'], ['night', 'Summary'], ['player', 'Players']];
// One pull or all pulls (S.scope): Summary is the all-pulls page (every pull's mechanics and assignments, with their
