    const head = 'M' + x1.toFixed(1) + ' ' + y1.toFixed(1) + 'L' + (hx - uy * 5).toFixed(1) + ' ' + (hy + ux * 5).toFixed(1) + 'L' + (hx + uy * 5).toFixed(1) + ' ' + (hy - ux * 5).toFixed(1) + 'Z';
