      '<path d="' + band + '" fill="none" stroke="' + col + '" stroke-opacity="' + (l.on ? 1 : 0.6) + '" stroke-width="' + (l.on ? 2 : 1.4) + '"' + (dud ? ' stroke-dasharray="5 4"' : '') + ' vector-effect="non-scaling-stroke"/>';
