    s += '<circle cx="' + cx + '" cy="' + cy + '" r="' + (big ? (p.b.kill ? 6 : 4) : p.b.kill ? 3.5 : 2) + '" class="' + (p.b.kill ? 'tk' : 'tw') + '"' + (p.b.kill ? '' : ' style="fill:' + (pullCol(p.b) || '#9d9d9d') + '"') + '>' + (big ? '' : '<title>Pull ' + p.b.pull + ': ' + esc(pullLabel(p.b)) + '</title>') + '</circle>';
