    s += '<g class="mp-s' + off(x.p.name) + '" data-n="' + esc(x.p.name) + '"><polyline points="' + line + '" class="pfc-l" style="stroke:' + x.p.color + (x.dash ? ';stroke-dasharray:6 4' : '') + '"/>';
