      if (ok.length) list += '<div class="pi-okl"><span class="okv">✓ ' + plural(ok.length, 'good cast') + ':</span> ' + [...grp.values()].sort((a, b) => b.k - a.k).map((y) => who(y.q) + ' <span class="sub">' + esc(piLc(y.pill)) + ' ×' + y.k + '</span>').join('<span class="sub"> · </span>') + '</div>';
