  const tl = one && per.length === 1 ? hpalTimeline(per[0], { hs: rows[0].hs, virtue, wingN, capL: rows[0].capL, ioHeld: ioOf(per[0].p), hpL: rows[0].hpL, hpCapL: rows[0].hpCapL, mnL: rows[0].mnL, jio: rows[0].m.jio || [] }) : '';
