  const jt = by('Judgment').concat(by('Hammer of Wrath')), jio = new Set((o.jio || []).map((t) => t.toFixed(2)));
  if (jt.length) h += row('Judgment', ticks(jt.filter((t) => !jio.has(t.toFixed(2))), 'thin') + ticks(jt.filter((t) => jio.has(t.toFixed(2))), 'io'));
