  const step = dur > 400 || (document.documentElement.clientWidth || 1000) < 700 ? 60 : 30, ax = []; for (let t = 0; t <= dur; t += step) ax.push('<span style="left:' + (100 * t / dur).toFixed(2) + '%">' + T(t) + '</span>');
