  for (const c of checks) { c.cost = rows.reduce((v, s) => v + ((s.cost && s.cost[c.k]) || 0), 0); if (c.cost >= 20000 && (c.st === 'warn' || c.st === 'bad')) c.sub += ' That cost about ' + C(c.cost) + ' ' + UN + ', ' + (c.cost / allHeal < 0.01 ? 'under 1%' : pct(c.cost / allHeal)) + ' of yours.'; }
  const sumBar = spcSumBar;
  const boxes = (c) => spcBoxes(one, c.bx);
  const countBx = spcCountBx;
  const area = (pts, top, step, cls) => { if (!pts || !pts.length) return ''; let d = 'M' + pts[0][0].toFixed(1) + ',10', prev = null; const t1 = X1.t1;
    for (const [t, v] of pts) { if (t > t1) break; const y = (10 - 10 * v / top).toFixed(2); if (step && prev != null) d += ' L' + t.toFixed(1) + ',' + prev; d += ' L' + t.toFixed(1) + ',' + y; prev = y; }
    return '<path d="' + d + ' L' + t1.toFixed(1) + ',' + (prev || 10) + ' L' + t1.toFixed(1) + ',10 Z" class="' + cls + '"/>'; };
  const rects = (l, cls, y, hh) => l.map(([a, b]) => '<rect x="' + a.toFixed(1) + '" y="' + (y || 0) + '" width="' + Math.max(0.6, b - a).toFixed(1) + '" height="' + (hh || 10) + '" rx=".6" class="' + cls + '"/>').join('');
  const lines = (l, cls) => l.map((t) => '<line x1="' + t.toFixed(2) + '" x2="' + t.toFixed(2) + '" y1="0" y2="10" class="' + cls + '"/>').join('');
