  $$('#main .pg-hub button.hc-card').forEach((b) => (b.onclick = () => { S.progView = b.dataset.g; S.pgRename = S.pgDel = S.pgEdit = false; if (b.dataset.g !== '*') store.set(GROUP_CUR, b.dataset.g); renderProgress(); window.scrollTo(0, 0); }));
